	for {
		msg, err := queue.Receive(ctx)
		if err != nil {
			if ctx.Err() != nil {
				return
			}
			continue
		}

		handleCtx, cancel := context.WithTimeout(ctx, 30*time.Second)
		err = handler.Handle(handleCtx, msg)
		cancel()

		if err != nil {
			_ = queue.Nack(context.Background(), msg)
			continue
		}

		_ = queue.Ack(context.Background(), msg)
	}
}
